import { CATEGORIES, STATUS, initialState, match, stats, transition, parseRequest, uid, audit, certificateEligibility, redeem } from './domain.js';
const STORAGE = 'silverlink-demo-v1';
const $ = s => document.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state;
try { const raw = JSON.parse(localStorage.getItem(STORAGE)); state = raw?.version === 1 && Array.isArray(raw.tasks) && raw.profile && raw.seed ? raw : initialState(); } catch { state = initialState(); }
let page = location.hash.slice(1).split('/')[0] || 'explore', filter = 'all', view = 'map', selected = 'SL-1001', zoom = 1, draft = null, storageFailed = false;
